const cfg = $('Brief Config').first().json;
const lead = Number(cfg.LeadTimeMinutes) || 60;
const briefInternal = String(cfg.BriefInternalMeetings).toLowerCase() === 'true';
const domains = String(cfg.InternalDomains || '').toLowerCase().split(',').map(d => d.trim()).filter(Boolean);
const interviewWords = String(cfg.InterviewKeywords || '').toLowerCase().split(',').map(w => w.trim()).filter(Boolean);
const logRows = $('Load Brief Log').all().map(i => i.json).filter(r => !r.error);
const briefedIds = new Set(logRows.map(r => String(r['Event ID'] || '')));
const events = $('Get Upcoming Meetings').all().map(i => i.json).filter(e => !e.error);
const now = Date.now();
const out = [];
for (const e of events) {
  const id = String(e.id || '');
  if (!id || briefedIds.has(id)) continue;
  if (String(e.status || '') === 'cancelled') continue;
  const startStr = e.start && (e.start.dateTime || e.start.date);
  if (!startStr) continue;
  const minsAway = (new Date(startStr).getTime() - now) / 60000;
  if (minsAway < 0 || minsAway > lead) continue;
  const attendees = Array.isArray(e.attendees) ? e.attendees : [];
  const me = attendees.filter(a => a.self);
  if (me.length && String(me[0].responseStatus || '') === 'declined') continue;
  const external = attendees.filter(a => { const em = String(a.email || '').toLowerCase(); if (!em || a.self || a.resource) return false; return !domains.some(d => em.endsWith('@' + d)); });
  const title = String(e.summary || 'Untitled meeting');
  const seriesId = String(e.recurringEventId || '');
  const priorForSeries = seriesId ? logRows.filter(r => String(r['Series ID'] || '') === seriesId).pop() : null;
  let meetingType;
  if (interviewWords.some(w => title.toLowerCase().includes(w))) meetingType = 'interview';
  else if (priorForSeries) meetingType = 'recurring';
  else if (!external.length) meetingType = 'internal';
  else meetingType = 'external';
  if (meetingType === 'internal' && !briefInternal) continue;
  out.push({ json: { eventId: id, seriesId, meetingType, title, startsAt: startStr, minutesAway: Math.round(minsAway), location: String(e.location || ''), agenda: String(e.description || '').slice(0, 1500), externalEmails: external.map(a => a.email).join(', '), primaryContact: external.length ? external[0].email : '', attendeeCount: attendees.length, priorBrief: priorForSeries ? String(priorForSeries.Brief || '').slice(0, 2000) : '', priorDate: priorForSeries ? String(priorForSeries['Starts At'] || '') : '' } });
}
return out;

const m = $('Loop Meetings').first().json;
const msgs = m.primaryContact ? $input.all().map(i => i.json).filter(r => !r.error && (r.snippet || r.subject)) : [];
const history = msgs.length ? msgs.slice(0, 12).map(x => 'Subject: ' + (x.subject || '(none)') + '
' + String(x.snippet || '').slice(0, 300)).join('

') : 'No prior email with this candidate.';
const instruction = 'This is an INTERVIEW. Write: WHO (candidate name and the role they are up for, only if the emails make it clear), ALREADY COVERED (what previous rounds or emails already established - do not re-ask these), STILL UNKNOWN (the gaps worth using this interview on), OPEN WITH (two specific questions). If there is no history, say this is a first-round conversation and base the opening questions on the role in the invite title.';
const context = 'Meeting: ' + m.title + '
Starts in: ' + m.minutesAway + ' min
Candidate: ' + (m.primaryContact || 'no external attendee on the invite') + '
Invite notes: ' + (m.agenda || 'none provided') + '

Email history:
' + history;
return [{ json: { type: 'interview', instruction, context } }];

const m = $input.item.json;
const instruction = 'This is a RECURRING meeting you have had before. Do not brief from scratch. Write: SINCE LAST TIME (what was open at the end of the previous brief, and therefore what should be closed out today), CARRY OVER (anything from last time still unresolved), TODAY (one line on what this session should achieve). If the previous brief is thin, say so plainly and keep it to two lines.';
const context = 'Meeting: ' + m.title + '
Starts in: ' + m.minutesAway + ' min
Attendees: ' + (m.externalEmails || 'internal only') + '
Agenda today: ' + (m.agenda || 'none provided') + '

Previous session: ' + (m.priorDate || 'unknown date') + '. The brief sent last time said:
' + (m.priorBrief || 'No previous brief content stored.');
return { json: { type: 'recurring', instruction, context } };

const m = $input.item.json;
const instruction = 'This is an INTERNAL meeting. Three lines maximum. Write: PURPOSE (one line, from the invite) and YOUR PART (what this person likely needs to bring or decide). Nothing else - no research, no relationship history, no talking points. If the invite has no agenda, say the agenda is missing and suggest asking for one.';
const context = 'Meeting: ' + m.title + '\nStarts in: ' + m.minutesAway + ' min\nAttendees: ' + m.attendeeCount + ' people, all internal\nAgenda from invite: ' + (m.agenda || 'none provided');
return { json: { type: 'internal', instruction, context } };

const m = $('Loop Meetings').first().json;
const msgs = m.primaryContact ? $input.all().map(i => i.json).filter(r => !r.error && (r.snippet || r.subject)) : [];
const hasHistory = msgs.length > 0;
const domain = String(m.primaryContact || '').split('@')[1] || 'unknown';
let instruction;
let context;
if (hasHistory) {
  const history = msgs.slice(0, 12).map(x => 'Subject: ' + (x.subject || '(none)') + '
' + String(x.snippet || '').slice(0, 300)).join('

');
  instruction = 'This is an EXTERNAL meeting with an existing relationship. Write: WHERE WE LEFT OFF (from the email history), OPEN THREADS (anything promised or unanswered that is visible in the emails - write "nothing outstanding" if there is none), GO IN WITH (two or three specific things to raise). Never invent a fact that is not in the history.';
  context = 'Meeting: ' + m.title + '
Starts in: ' + m.minutesAway + ' min
With: ' + m.externalEmails + '
Agenda: ' + (m.agenda || 'none provided') + '

Email history (' + msgs.length + ' messages):
' + history;
} else {
  instruction = 'This is a FIRST CONVERSATION with someone external - there is no email history, so do not imply a relationship exists. Write: WHAT WE KNOW (only what the invite and their email domain actually tell you), WHAT TO ESTABLISH (two or three things worth finding out in a first conversation), OPEN WITH (one specific opening question based on the invite). Be explicit that this is a cold first meeting.';
  context = 'Meeting: ' + m.title + '
Starts in: ' + m.minutesAway + ' min
With: ' + m.externalEmails + '
Their domain: ' + domain + '
Agenda from invite: ' + (m.agenda || 'none provided') + '

No prior email found with this contact.';
}
return [{ json: { type: hasHistory ? 'external' : 'external_new', instruction, context } }];

parameters.text:
=You write pre-meeting briefs that get read on a phone, minutes before the meeting starts.

Your instruction for this specific meeting:
{{ $json.instruction }}

The meeting:
{{ $json.context }}

Rules that always apply: no invented facts, no filler, no pleasantries, no restating the instruction back. Use the exact section headings named in the instruction and nothing else. A short honest brief beats a padded one.

